<?php
declare(strict_types=1);
final class PortableRecords {
 public static function targets():array{return ['contacts'=>['label'=>t('People contacts'),'module'=>'LifePlanning','table'=>'life_contacts','service'=>LifePlanningService::class,'kind'=>'contacts','fields'=>['name','phone','email','birthday','next_followup','notes']],'study_notes'=>['label'=>t('Module study notes'),'module'=>'StudyTools','table'=>'study_records','service'=>StudyService::class,'kind'=>'notes','fields'=>array_keys(StudyService::catalog()['notes'][1])],'portfolio'=>['label'=>t('Academic portfolio evidence'),'module'=>'StudyTools','table'=>'study_records','service'=>StudyService::class,'kind'=>'portfolio','fields'=>array_keys(StudyService::catalog()['portfolio'][1])],'achievements'=>['label'=>t('Employee achievements'),'module'=>'Employee','table'=>'employee_records','service'=>EmployeeService::class,'kind'=>'achievements','fields'=>array_keys(EmployeeService::catalog()['achievements'][1])]];}
 public static function target(string $id):array{$t=self::targets()[$id]??throw new InvalidArgumentException(t('Choose a supported record import.'));if(!module_enabled($t['module']))throw new InvalidArgumentException(t('Enable the destination module first.'));return $t;}
 public static function raw(string $text,string $format):array{
  if(strlen($text)>2097152)throw new InvalidArgumentException(t('Import at most 2 MiB.'));if($format==='json'){$rows=json_decode($text,true,32,JSON_THROW_ON_ERROR);if(!is_array($rows)||!array_is_list($rows))throw new InvalidArgumentException(t('Expected a JSON list.'));}
  elseif(in_array($format,['csv','notion','todoist'],true)){$f=fopen('php://temp','w+');fwrite($f,$text);rewind($f);try{$head=fgetcsv($f,0,',','"','');if(!$head)throw new InvalidArgumentException(t('CSV needs column headings.'));$head=array_map(fn($v)=>mb_strtolower(trim(ltrim((string)$v,"\xef\xbb\xbf"))),$head);if(count($head)!==count(array_unique($head)))throw new InvalidArgumentException(t('Use unique CSV column headings.'));$rows=[];while(($row=fgetcsv($f,0,',','"',''))!==false){if($row===[null])continue;if(count($row)!==count($head))throw new InvalidArgumentException(t('Column count differs from the header.'));$rows[]=array_combine($head,$row);if(count($rows)>1000)throw new InvalidArgumentException(t('Import at most 1000 records.'));}}finally{fclose($f);}}
  else throw new InvalidArgumentException(t('Choose CSV, Notion CSV, Todoist CSV, JSON or an XLSX file.'));if(count($rows)>1000)throw new InvalidArgumentException(t('Import at most 1000 records.'));$clean=[];foreach($rows as $row){if(!is_array($row))throw new InvalidArgumentException(t('Invalid record row.'));$r=[];foreach($row as $k=>$v){if(!is_string($k)||strlen($k)>100||!is_scalar($v)&&$v!==null||is_bool($v))throw new InvalidArgumentException(t('Use scalar values and short column names.'));$r[mb_strtolower(trim($k))]=$v===null?'':(string)$v;}$clean[]=$r;}return $clean;
 }
 public static function prepare(string $target,array $rows,array $mapping,?int $module=null):array{$t=self::target($target);$prepared=[];foreach($rows as $i=>$row){$d=[];foreach($t['fields']as $field){$source=$mapping[$field]??$field;if(!is_string($source))throw new InvalidArgumentException(t('Choose a source column for ').$field.'.');$d[$field]=$source==='__module'?(string)($module??''):($source===''?'':($row[$source]??''));}
   try{if($target==='contacts'){if(trim($d['name'])===''||mb_strlen($d['name'])>200)throw new InvalidArgumentException(t('Name is required (up to 200 characters).'));foreach($d as $v)if(mb_strlen($v)>2000||str_contains($v,"\0"))throw new InvalidArgumentException(t('Contact field too long.'));foreach(['birthday','next_followup']as $f)if($d[$f]!=='')valid_date($d[$f]);}
    else{if(isset($d['module_id'])&&!ctype_digit($d['module_id'])){$matches=Db::all('SELECT id FROM uni_modules WHERE code=? OR name=?',[$d['module_id'],$d['module_id']]);if(count($matches)!==1)throw new InvalidArgumentException(t('Select an existing module or map a unique module code/name.'));$d['module_id']=(string)$matches[0]['id'];}$service=$t['service'];$d=$service::normalizeInput($t['kind'],$d);}$prepared[]=$d;}catch(InvalidArgumentException $e){throw new InvalidArgumentException(t('Row ').($i+1).': '.$e->getMessage());}}
  return $prepared;
 }
 public static function import(string $target,array $prepared):int{$t=self::target($target);$hash=hash('sha256',$target.':'.json_encode($prepared));return Db::tx(function()use($t,$target,$prepared,$hash){if(Db::one('SELECT id FROM platform_imports WHERE hash=?',[$hash]))throw new InvalidArgumentException(t('This record import was already applied.'));$batch=Db::run('INSERT INTO platform_imports(hash,target) VALUES(?,?)',[$hash,$target]);foreach($prepared as $row){$service=$t['service'];$input=array_map(fn($v)=>$v===null?'':(string)$v,$row);$id=$target==='contacts'?$service::save('contacts',$input,null,false):$service::save($t['kind'],$input,null,false);$saved=Db::one('SELECT * FROM '.$t['table'].' WHERE id=?',[$id]);Db::run('INSERT INTO platform_changes(batch_id,entity,row_id,after_json) VALUES(?,?,?,?)',[$batch,$t['table'],$id,json_encode($saved)]);}PlatformService::audit('records-imported',$target.' · '.count($prepared).' records · batch '.$batch);return $batch;});}
 public static function undo(int $batch):void{$b=Db::one('SELECT target FROM platform_imports WHERE id=?',[$batch]);$t=self::target($b['target']??'');Db::tx(function()use($batch,$t){$changes=Db::all('SELECT * FROM platform_changes WHERE batch_id=? AND undone=0',[$batch]);if(!$changes)throw new InvalidArgumentException(t('No pending import changes.'));foreach($changes as $c){$r=Db::one('SELECT * FROM '.$t['table'].' WHERE id=?',[$c['row_id']]);if($c['entity']!==$t['table']||$r!==json_decode($c['after_json'],true))throw new InvalidArgumentException(t('An imported record changed. Undo stopped.'));PlatformService::assertUnreferenced($t['table'],(int)$c['row_id']);if($t['table']==='life_contacts'&&Db::one("SELECT row_id FROM life_archives WHERE entity='contacts' AND row_id=?",[$c['row_id']]))throw new InvalidArgumentException(t('Record was archived after import. Keep that later change.'));}foreach($changes as $c){Db::run('DELETE FROM '.$t['table'].' WHERE id=?',[$c['row_id']]);Db::run('UPDATE platform_changes SET undone=1 WHERE id=?',[$c['id']]);}PlatformService::audit('record-import-undone','Batch '.$batch);});}
 public static function csv(string $target):string{$t=self::target($target);$f=fopen('php://temp','w+');fwrite($f,"\xef\xbb\xbf");fputcsv($f,$t['fields'],',','"','');$service=$t['service'];$rows=$target==='contacts'?$service::rows('contacts'):$service::rows($t['kind']);foreach($rows as $row){$d=$row['fields']??$row;$values=[];foreach($t['fields']as $field){$v=(string)($d[$field]??'');$values[]=preg_match('/^[=+@\-\t\r]/',$v)?"'".$v:$v;}fputcsv($f,$values,',','"','');}rewind($f);$out=stream_get_contents($f);fclose($f);return $out;}
}
